"""Controlled C# editor drafts; real DOM, simulated metadata, no compiler claims."""
import http.server,json,pathlib,sys,tempfile,threading
from playwright.sync_api import sync_playwright,expect

repo=pathlib.Path(sys.argv[1]).resolve();case=pathlib.Path(tempfile.mkdtemp(prefix='confectory-callee-out-value-renderer-'));checks=[];errors=[]
class Handler(http.server.SimpleHTTPRequestHandler):
 def __init__(self,*a,**kw):super().__init__(*a,directory=str(repo),**kw)
 def log_message(self,*a):pass
server=http.server.ThreadingHTTPServer(('127.0.0.1',0),Handler);threading.Thread(target=server.serve_forever,daemon=True).start()
bootstrap=r"""async()=>{
 const {createFeatureAuthoring}=await import('/examples/editor-home/ui/feature-authoring.js');
 const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],esc=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
 const before={args:[{name:'amount',type:'long'},{name:'count',type:'long',mode:'out'}],return:'long'},contract=structuredClone(before),native={args:[{name:'nativeAmount',type:'long'},{name:'nativeCount',type:'long',mode:'out'}],return:'long'};
 const text='nativeCount=40;return checked(nativeAmount+nativeCount); // 한글 😀\r\n',row={hash:'a'.repeat(64),sourceKind:'csharp',signature:native,contractSignature:before,text,path:'B.csbody'},state={saved:{},drafts:JSON.parse(sessionStorage.aliasDrafts||'{}'),commits:[],toasts:[]};
 const controller=createFeatureAuthoring({$,$$,esc,authorInputs:new Map(),toast:t=>state.toasts.push(t),modal:(title,html,mount)=>{const root=document.createElement('section');root.setAttribute('role','dialog');root.innerHTML=html;document.body.append(root);mount(root,()=>root.remove());}});
 globalThis.fixture={state,row,contract,text,open:()=>{controller.editInformationBodies({allowNativeRoles:false,title:'별칭 보존',rows:{body:row,privateCaller:{sourceKind:'scoped-code-csharp',caller:true,name:'원래 private caller'}},contract,alive:()=>true,saved:state.saved,drafts:state.drafts,retain:(id,v)=>{state.drafts[id]=v;sessionStorage.aliasDrafts=JSON.stringify(state.drafts);},cancel:()=>{},commit:(id,v)=>state.commits.push(v)});document.querySelector('[data-information-body=body]')?.click();},drop:()=>document.querySelector('[role=dialog]')?.remove()};
}"""
def checked(label):checks.append(label);print('PASS '+label,flush=True)
def header():return page.locator('[data-code-source]').input_value().split('\n{',1)[0]
def body(text):
 field=page.locator('[data-code-source]');field.evaluate('(el)=>{const s=[...el.closest(".bp-script-editor").querySelectorAll("[data-code-highlight]>span")],b=s.find(v=>v.dataset.codeRegion==="body"),start=s.slice(0,s.indexOf(b)).reduce((n,v)=>n+v.textContent.length,0);if(!b)throw Error("missing body");el.focus();el.setSelectionRange(start,start+b.textContent.length)}');page.keyboard.insert_text(text)
def parameters(text):
 field=page.locator('[data-code-source]');field.evaluate("el=>{el.focus();el.setSelectionRange(el.value.indexOf('(')+1,el.value.indexOf(')'));}");page.keyboard.insert_text(text)
try:
 with sync_playwright() as p:
  expect.set_options(timeout=10000);browser=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);page=browser.new_page();page.on('pageerror',lambda e:errors.append(str(e)));page.goto('http://127.0.0.1:'+str(server.server_port)+'/');page.evaluate(bootstrap)
  page.evaluate('()=>fixture.open()');original=page.evaluate('()=>fixture.text');assert header()=='public long Invoke(long nativeAmount, out long nativeCount)';parameters('long nativeAmount, long nativeCount');page.locator('[data-code-save]').click();accepted=page.evaluate('()=>fixture.state.commits.at(-1)');assert accepted['text']==original and 'mode'not in accepted['contract']['args'][1] and accepted['signature']['args'][1]==dict(name='nativeCount',type='long');checked('explicit role-only Code Save retains original CSharp bytes without deleting the original assignment or rewriting its CSharp')
  page.evaluate('()=>{fixture.state.drafts={};fixture.open()}');parameters('long nativeAmount, long nativeCount');body('return nativeAmount-nativeCount; // 명시 값 소비 😀\n');draft=page.evaluate('()=>fixture.state.drafts.body');assert draft['parameters']=='long nativeAmount, long nativeCount';(case/'retained-draft.json').write_text(json.dumps(draft,ensure_ascii=False,indent=2));page.reload();page.evaluate(bootstrap);page.evaluate('()=>fixture.open()');assert header()=='public long Invoke(long nativeAmount, long nativeCount)';page.locator('[data-code-save]').click();raw_accepted=page.evaluate('()=>fixture.state.commits.at(-1)');accepted=json.loads(page.evaluate('()=>JSON.stringify(fixture.state.commits.at(-1))'));(case/'accepted-comparison.json').write_text(json.dumps(dict(raw=raw_accepted,wire=accepted,original=page.evaluate('()=>fixture.row.signature'),draft=draft),ensure_ascii=False,indent=2));assert accepted['text']==draft['text']and accepted['beforeSignature']==page.evaluate('()=>fixture.row.signature')and accepted['signature']['return']=='long'and accepted['contract']['args'][1]==dict(name='count',type='long');checked('explicit source/parameter draft survives fresh renderer and retains native aliases, original return and public value identity')
  first=json.loads(page.evaluate('()=>JSON.stringify(fixture.state.commits.at(-1))'));page.evaluate('(plan)=>{fixture.state.saved={body:plan};Object.assign(fixture.contract,structuredClone(plan.contract));fixture.state.drafts={};fixture.open()}',first);assert header()=='public long Invoke(long nativeAmount, long nativeCount)';page.locator('[data-code-save]').click();again=json.loads(page.evaluate('()=>JSON.stringify(fixture.state.commits.at(-1))'));assert again==first,(first,again);checked('before first owner Save, Code Save reentry keeps the exact explicit native value/source plan')
  page.evaluate('()=>fixture.open()');body('return nativeAmount-nativeCount; // 재진입 값 초안 😀\n');draft=page.evaluate('()=>fixture.state.drafts.body');assert draft['parameters']=='long nativeAmount, long nativeCount';page.reload();page.evaluate(bootstrap);page.evaluate('(plan)=>{fixture.state.saved={body:plan};Object.assign(fixture.contract,structuredClone(plan.contract));fixture.open()}',first);assert header()=='public long Invoke(long nativeAmount, long nativeCount)';page.locator('[data-code-save]').click();again=json.loads(page.evaluate('()=>JSON.stringify(fixture.state.commits.at(-1))'));assert again['signature']==first['signature']and again['text']==draft['text'];checked('readonly value reentry draft survives fresh renderer with its original native value marker and explicit text')
  page.evaluate('()=>{fixture.state.saved={};fixture.state.drafts={};fixture.contract.args[1].mode="out";}')
  for bad in ['long nativeAmount, ref long nativeCount','out long nativeAmount, long nativeCount','long nativeAmount, long guessedCount']:
   page.evaluate('()=>{fixture.state.drafts={};fixture.open()}');parameters(bad);before=page.evaluate('()=>fixture.state.commits.length');page.locator('[data-code-save]').click();expect(page.locator('[data-code-error]')).to_be_visible();assert page.evaluate('()=>fixture.state.commits.length')==before and page.evaluate('()=>fixture.state.drafts.body.parameters')==bad;page.locator('[data-code-cancel]').click();checked('scoped-caller role editor rejects '+bad+' while retaining the draft')
  page.evaluate('()=>{fixture.state.drafts={body:{hash:"b".repeat(64),text:"unconfirmed"}};fixture.open()}');expect(page.locator('[role=dialog]')).to_have_count(0);assert page.evaluate('()=>fixture.state.drafts.body.text')=='unconfirmed';assert not errors,errors;checked('changed original source hash rejects reentry without losing draft text');browser.close()
finally:server.shutdown()
record=dict(controlledRenderer=True,actualEngine=False,checks=checks,evidence=str(case));(case/'evidence.json').write_text(json.dumps(record,ensure_ascii=False,indent=2));print(json.dumps(record,ensure_ascii=False))

